343	/// Export to HTML.
344	fn export_html(document: &HtmlDocument, config: &CompileConfig) -> SourceResult<()> {
345	    let options = HtmlOptions { pretty: config.pretty };
346	    let html = typst_html::html(document, &options)?;
347	    let result = config.output.write(html.as_bytes());
348	
349	    #[cfg(feature = "http-server")]
350	    if let Some(server) = &config.server {
351	        server.set_html(html);
352	    }
353	
354	    result
355	        .map_err(|err| eco_format!("failed to write HTML file ({err})"))
356	        .at(Span::detached())
